import { useState, useEffect, useRef } from "react";

// ─── Hooks ────────────────────────────────────────────────────────────────────

function useInView(threshold = 0.1) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const obs = new IntersectionObserver(
      ([e]) => { if (e.isIntersecting) setVisible(true); },
      { threshold }
    );
    obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function useHover() {
  const [on, setOn] = useState(false);
  return [on, { onMouseEnter: () => setOn(true), onMouseLeave: () => setOn(false) }];
}

function useWindowWidth() {
  const [w, setW] = useState(
    typeof window !== "undefined" ? window.innerWidth : 1200
  );
  useEffect(() => {
    const h = () => setW(window.innerWidth);
    window.addEventListener("resize", h);
    return () => window.removeEventListener("resize", h);
  }, []);
  return w;
}

// Animates a numeric string from 0 → target when triggered
function useCounter(value, triggered) {
  const [display, setDisplay] = useState(value);
  useEffect(() => {
    if (!triggered) return;
    const num = parseFloat(value);
    if (isNaN(num)) { setDisplay(value); return; }
    const suffix = value.replace(/^[\d.]+/, "");
    const isDecimal = value.includes(".");
    const start = performance.now();
    const dur = 1000;
    const tick = (now) => {
      const t = Math.min((now - start) / dur, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      const current = eased * num;
      setDisplay((isDecimal ? current.toFixed(1) : Math.round(current)) + suffix);
      if (t < 1) requestAnimationFrame(tick);
      else setDisplay(value);
    };
    requestAnimationFrame(tick);
  }, [triggered, value]);
  return display;
}

// Types text out character by character; returns [displayed, isDone]
function useTypewriter(text, speed = 38, started = false) {
  const [displayed, setDisplayed] = useState("");
  const [done, setDone] = useState(false);
  useEffect(() => {
    if (!started) return;
    setDisplayed(""); setDone(false);
    let i = 0;
    const id = setInterval(() => {
      i++;
      setDisplayed(text.slice(0, i));
      if (i >= text.length) { clearInterval(id); setDone(true); }
    }, speed);
    return () => clearInterval(id);
  }, [started, text, speed]);
  return [displayed, done];
}

// Returns scrollY offset — used for parallax transforms
function useParallax(factor = 0.28) {
  const [offset, setOffset] = useState(0);
  useEffect(() => {
    const h = () => setOffset(window.scrollY * factor);
    window.addEventListener("scroll", h, { passive: true });
    return () => window.removeEventListener("scroll", h);
  }, [factor]);
  return offset;
}

// Bidirectional scroll fade — dissolves out when scrolled past, fades in on entry
function useScrollFade() {
  const ref = useRef(null);
  const [s, setS] = useState({ opacity: 0, transform: "translateY(20px)" });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const update = () => {
      const { top, bottom } = el.getBoundingClientRect();
      const vh = window.innerHeight;

      // Not yet reached — waiting below viewport
      if (top > vh + 40) {
        setS({ opacity: 0, transform: "translateY(24px)" });
        return;
      }
      // Scrolled past — dissolving upward out of viewport
      if (bottom < -40) {
        setS({ opacity: 0, transform: "translateY(-20px)" });
        return;
      }
      // Entering from bottom
      if (top > 0) {
        const p = Math.min(1, (vh - top) / (vh * 0.3));
        const eased = 1 - Math.pow(1 - p, 2);
        setS({ opacity: eased, transform: `translateY(${(1 - eased) * 20}px)` });
        return;
      }
      // Exiting through top — fade as last 25% of section clears the nav
      if (bottom > 0 && bottom < vh * 0.28) {
        const p = Math.min(1, bottom / (vh * 0.28));
        const eased = 1 - Math.pow(1 - p, 2);
        setS({ opacity: eased, transform: `translateY(${-(1 - eased) * 14}px)` });
        return;
      }
      // Fully in view
      setS({ opacity: 1, transform: "translateY(0)" });
    };

    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update, { passive: true });
    update();
    return () => {
      window.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, []);

  return [ref, s];
}

