const getC = (dark) => dark
  ? { bg: "#0a0a0a", ink: "#ececec", mid: "#b8b8b8", muted: "#707070", faint: "#404040", border: "#222222", navBg: "rgba(10,10,10,0.96)" }
  : { bg: "#f7f5f0", ink: "#0a0a0a", mid: "#3a3a3a", muted: "#808080", faint: "#aaaaaa", border: "#e0ddd6", navBg: "rgba(247,245,240,0.96)" };

const getGlass = (dark, on) => !on ? {} : dark
  ? { background: "rgba(160,200,255,0.07)", backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", borderColor: "rgba(160,200,255,0.22)", boxShadow: "0 2px 14px rgba(120,170,255,0.10), inset 0 1px 0 rgba(255,255,255,0.06)" }
  : { background: "rgba(80,130,230,0.055)", backdropFilter: "blur(20px)", WebkitBackdropFilter: "blur(20px)", borderColor: "rgba(80,130,230,0.22)",   boxShadow: "0 2px 14px rgba(80,130,230,0.08),  inset 0 1px 0 rgba(255,255,255,0.7)" };

