const SM   = 640;

// ─── Shared components ────────────────────────────────────────────────────────

function Fade({ children, delay = 0, style = {} }) {
  const [ref, visible] = useInView();
  return (
    <div ref={ref} style={{
      opacity:    visible ? 1 : 0,
      transform:  visible ? "translateY(0)" : "translateY(16px)",
      transition: `opacity 0.55s ease ${delay}ms, transform 0.55s ease ${delay}ms`,
      ...style,
    }}>
      {children}
    </div>
  );
}

// Wraps a full <section> — dissolves out scrolling past, fades in on entry
function ScrollSection({ children, style = {} }) {
  const [ref, s] = useScrollFade();
  return (
    <div ref={ref} style={{ transition: "opacity 0.42s ease, transform 0.42s ease", ...s, ...style }}>
      {children}
    </div>
  );
}

function GlassBtn({ children, href, onClick, solid, C, dark, style: extra = {} }) {
  const [hov, hp] = useHover();
  const g = getGlass(dark, hov);
  const s = {
    display: "inline-flex", alignItems: "center", gap: 6,
    padding: "9px 17px", borderRadius: 100, fontSize: 14,
    fontWeight: 400, fontFamily: sans, textDecoration: "none",
    letterSpacing: "-0.01em", cursor: "pointer",
    background:  solid ? C.ink : (hov ? g.background : "transparent"),
    color:       solid ? C.bg  : C.mid,
    border:      solid ? "none" : `1px solid ${hov ? (g.borderColor || C.border) : C.border}`,
    backdropFilter:       !solid && hov ? g.backdropFilter       : "none",
    WebkitBackdropFilter: !solid && hov ? g.WebkitBackdropFilter : "none",
    boxShadow: hov ? (solid
      ? dark ? "0 2px 16px rgba(120,170,255,0.18)" : "0 2px 16px rgba(80,130,230,0.14)"
      : g.boxShadow) : "none",
    opacity: solid && hov ? 0.86 : 1,
    transition: "background .22s, border-color .22s, box-shadow .22s, color .3s, opacity .22s",
    ...extra,
  };
  return href
    ? <a href={href} onClick={onClick} target="_blank" rel="noopener noreferrer" style={s} {...hp}>{children}</a>
    : <button onClick={onClick} style={s} {...hp}>{children}</button>;
}

function NavPill({ children, onClick, C, dark, active }) {
  const [hov, hp] = useHover();
  const g = getGlass(dark, hov);
  return (
    <button onClick={onClick} style={{
      background:           hov ? g.background    : "none",
      backdropFilter:       hov ? g.backdropFilter : "none",
      WebkitBackdropFilter: hov ? g.WebkitBackdropFilter : "none",
      border:       `1px solid ${hov ? (g.borderColor || "transparent") : "transparent"}`,
      borderRadius: 100, padding: "4px 11px", cursor: "pointer",
      fontFamily: sans, fontSize: 14,
      fontWeight: active ? 500 : 400,
      color:      active ? C.ink : C.muted,
      boxShadow:  hov ? g.boxShadow : "none",
      position:   "relative",
      transition: "background .22s, border-color .22s, box-shadow .22s, color .25s",
    }} {...hp}>
      {children}
      <span style={{
        position: "absolute", bottom: 2, left: "50%", transform: "translateX(-50%)",
        width: active ? 3 : 0, height: 3, borderRadius: "50%",
        background: BRASS, transition: "width .25s",
      }} />
    </button>
  );
}

