// ─── Investigations page ──────────────────────────────────────────────────────

function InvestigationsPage({ dark, setDark, goHome }) {
  const C = getC(dark);
  const width = useWindowWidth();
  const isMobile = width < SM;
  const [activeTag, setTag] = useState("All");
  const [thHov, thHovP] = useHover();
  const px = isMobile ? "20px" : "clamp(24px,5vw,48px)";
  const inner = { maxWidth: W, margin: "0 auto" };

  const total    = CATEGORIES.reduce((a, c) => a + c.items.length, 0);
  const filtered = activeTag === "All"
    ? total
    : CATEGORIES.reduce((a, c) => a + c.items.filter(i => i.tags.includes(activeTag)).length, 0);

  return (
    <div style={{ background: C.bg, color: C.ink, fontFamily: sans, minHeight: "100vh", WebkitFontSmoothing: "antialiased", transition: "background .3s, color .3s" }}>

      {/* Fixed nav */}
      <nav style={{ position: "fixed", top: 0, left: 0, right: 0, zIndex: 200, height: 52, padding: `0 ${px}`, display: "flex", alignItems: "center", justifyContent: "space-between", background: C.navBg, backdropFilter: "blur(16px)", WebkitBackdropFilter: "blur(16px)", borderBottom: `1px solid ${C.border}`, transition: "background .3s, border-color .3s" }}>
        <button onClick={goHome} style={{ display: "flex", alignItems: "center", gap: 6, background: "none", border: "none", cursor: "pointer", fontFamily: sans, fontSize: 15, fontWeight: 500, color: C.ink, letterSpacing: "-.015em", transition: "opacity .18s" }}
          onMouseEnter={e => e.currentTarget.style.opacity = ".6"}
          onMouseLeave={e => e.currentTarget.style.opacity = "1"}
        >
          <span style={{ fontSize: 16 }}>←</span> yambo.
        </button>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {!isMobile && <span style={{ fontSize: 13, color: C.faint, marginRight: 6 }}>Investigations</span>}
          <ThemeBtn dark={dark} setDark={setDark} C={C} themeHv={thHov} themeHvP={thHovP} />
        </div>
      </nav>

      {/* Header */}
      <section style={{ padding: `clamp(48px,8vw,72px) ${px} clamp(24px,4vw,40px)` }}>
        <div style={{ ...inner }}>
          <p style={{ fontSize: 13, color: C.faint, marginBottom: 8 }}>{filtered} of {total} investigations</p>
          <h1 style={{ fontFamily: sans, fontSize: "clamp(32px,6vw,58px)", fontWeight: 500, letterSpacing: "-.035em", lineHeight: 1.05, margin: "0 0 14px", color: C.ink }}>
            All Investigations
          </h1>
          <p style={{ fontSize: "clamp(15px,2vw,18px)", fontWeight: 300, color: C.faint, margin: "0 0 32px", maxWidth: 480, lineHeight: 1.6 }}>
            Open-source reporting across conflict, accountability, and data journalism in Africa.
          </p>
          {/* Tag filters */}
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {ALL_TAGS.map(tag => {
              const active = activeTag === tag;
              return (
                <button key={tag} onClick={() => setTag(tag)} style={{
                  padding: "6px 14px", borderRadius: 100, fontSize: 13,
                  fontWeight: active ? 500 : 400, cursor: "pointer", fontFamily: sans,
                  background: active ? BRASS          : "transparent",
                  color:      active ? "#0a0a0a"      : C.muted,
                  border:     active ? "none"          : `1px solid ${C.border}`,
                  transition: "background .18s, color .18s, border-color .18s",
                }}>
                  {tag}
                </button>
              );
            })}
          </div>
        </div>
      </section>

      <HR C={C} />

      {/* Category sections */}
      <section style={{ padding: `clamp(32px,5vw,56px) ${px}` }}>
        <div style={{ ...inner }}>
          {CATEGORIES.map((cat, ci) => {
            const count = activeTag === "All" ? cat.items.length : cat.items.filter(i => i.tags.includes(activeTag)).length;
            if (count === 0 && activeTag !== "All") return null;
            return (
              <Fade key={cat.id} delay={ci * 55} style={{ marginBottom: 52 }}>
                <div style={{ display: "flex", alignItems: "baseline", gap: 12, marginBottom: 14, paddingBottom: 14, borderBottom: `1px solid ${C.border}` }}>
                  <h2 style={{ fontFamily: sans, fontSize: "clamp(17px,2.5vw,21px)", fontWeight: 500, letterSpacing: "-.02em", color: C.ink, margin: 0 }}>{cat.label}</h2>
                  <span style={{ fontSize: 13, color: C.faint }}>{count} {count === 1 ? "investigation" : "investigations"}</span>
                </div>
                <p style={{ fontSize: 14, color: C.muted, margin: "0 0 16px", lineHeight: 1.6, maxWidth: 520 }}>{cat.desc}</p>
                {cat.items.map((item, i) => {
                  const dimmed = activeTag !== "All" && !item.tags.includes(activeTag);
                  const [hov, hp] = [false, {}];
                  return (
                    <a key={item.href} href={item.href} target="_blank" rel="noopener noreferrer" style={{ textDecoration: "none", display: "block" }}>
                      <div style={{
                        padding: "18px 10px",
                        borderTop: `1px solid ${C.border}`,
                        borderBottom: i === cat.items.length - 1 ? `1px solid ${C.border}` : "none",
                        borderRadius: 8,
                        opacity: dimmed ? 0.25 : 1,
                        transition: "opacity .3s",
                      }}>
                        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", gap: 16 }}>
                          <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 6, flexWrap: "wrap" }}>
                              {item.featured && <span style={{ fontSize: 10, fontWeight: 500, letterSpacing: ".1em", color: "#0a0a0a", background: BRASS, padding: "2px 8px", borderRadius: 100, fontFamily: sans }}>FEATURED</span>}
                              {item.tags.map(t => <span key={t} style={{ fontSize: 11, padding: "2px 9px", borderRadius: 100, fontFamily: sans, background: activeTag === t ? C.ink : C.border, color: activeTag === t ? C.bg : C.muted, transition: "background .2s, color .2s" }}>{t}</span>)}
                            </div>
                            <h3 style={{ fontFamily: sans, fontSize: "clamp(14px,2vw,16px)", fontWeight: 500, color: C.ink, margin: "0 0 5px", letterSpacing: "-.015em", lineHeight: 1.3 }}>{item.title}</h3>
                            <p style={{ fontSize: 13, color: C.muted, lineHeight: 1.7, margin: 0 }}>{item.desc}</p>
                          </div>
                          <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 5, flexShrink: 0 }}>
                            <span style={{ fontSize: 11, color: C.faint }}>{item.year}</span>
                            <span style={{ fontSize: 11, color: C.faint, textAlign: "right", maxWidth: 110, lineHeight: 1.4 }}>{item.pub}</span>
                            <span style={{ fontSize: 14, color: C.faint }}>↗</span>
                          </div>
                        </div>
                      </div>
                    </a>
                  );
                })}
              </Fade>
            );
          })}
          {filtered === 0 && (
            <div style={{ textAlign: "center", padding: "56px 0" }}>
              <p style={{ fontSize: 15, color: C.faint, marginBottom: 14 }}>No investigations tagged "{activeTag}"</p>
              <button onClick={() => setTag("All")} style={{ padding: "8px 18px", borderRadius: 100, fontSize: 13, fontFamily: sans, cursor: "pointer", background: C.ink, color: C.bg, border: "none" }}>Show all</button>
            </div>
          )}
        </div>
      </section>

      <HR C={C} />
      <footer style={{ padding: `18px ${px}`, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
        <button onClick={goHome} style={{ background: "none", border: "none", cursor: "pointer", fontFamily: sans, fontSize: 14, color: C.faint, letterSpacing: "-.01em", transition: "color .18s" }}
          onMouseEnter={e => e.currentTarget.style.color = C.ink}
          onMouseLeave={e => e.currentTarget.style.color = C.faint}
        >← Back to home</button>
        <span style={{ fontSize: 13, color: C.faint }}>Mike Yambo</span>
      </footer>
    </div>
  );
}

function PubLogo({ src, name, height = 40, dark }) {
  const [hov, hp] = useHover();
  return (
    <div
      {...hp}
      title={name}
      style={{
        display: "flex", alignItems: "center", justifyContent: "center",
        cursor: "default", flexShrink: 0,
        opacity:   hov ? 1 : 0.65,
        transform: hov ? "scale(1.06)" : "scale(1)",
        transition: "opacity 0.25s ease, transform 0.25s ease, filter 0.25s ease",
        // Dark mode: invert so dark logos become light, light logos become dark
        filter: hov
          ? (dark ? "invert(1) brightness(1.1)" : "none")
          : dark
            ? "invert(1) brightness(0.85) opacity(0.65)"
            : "opacity(0.65)",
      }}
    >
      <img
        src={src}
        alt={name}
        style={{
          height,
          maxWidth: 160,
          objectFit: "contain",
          display: "block",
        }}
      />
    </div>
  );
}

