function HomePage({ dark, setDark, goInv }) {
  const C = getC(dark);
  const width    = useWindowWidth();
  const isMobile = width < SM;
  const isWide   = width >= 1440;
  const [menuOpen, setMenu] = useState(false);
  const [thHov,    thHovP]  = useHover();
  const [loaded,   setLoaded] = useState(false);

  useEffect(() => { setTimeout(() => setLoaded(true), 60); }, []);
  useEffect(() => {
    if (width >= 1024) setMenu(false);
  }, [width]);

  const parallaxY = useParallax(0.22);
  const TAGLINE    = "Investigating power through data and open sources.";
  const [typed, typeDone] = useTypewriter(TAGLINE, 36, loaded);
  const px  = isMobile ? "20px" : "clamp(24px,5vw,48px)";
  const sec = { padding: `clamp(40px,7vw,68px) ${px}` };
  const inn = { maxWidth: isWide ? "1100px" : W, margin: "0 auto" };

  // ── Search ──────────────────────────────────────────────────────────────────
  const [searchOpen,  setSearchOpen]  = useState(false);
  const [aboutOpen, setAboutOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const searchRef = useRef(null);

  // Flatten all searchable items
  const SEARCH_INDEX = [
    ...WORK.map(w => ({ title: w.title, desc: w.desc, href: w.href, meta: w.org + " · " + w.year, type: "Investigation" })),
    ...CATEGORIES.flatMap(c => c.items.map(i => ({ title: i.title, desc: i.desc, href: i.href, meta: i.pub + " · " + i.year, type: c.label }))),
  ].filter((v, i, arr) => arr.findIndex(x => x.href === v.href) === i); // dedupe

  const results = searchQuery.trim().length < 2 ? [] : SEARCH_INDEX.filter(item => {
    const q = searchQuery.toLowerCase();
    return item.title.toLowerCase().includes(q) || item.desc.toLowerCase().includes(q) || item.meta.toLowerCase().includes(q);
  }).slice(0, 7);

  // Focus input when modal opens
  useEffect(() => {
    if (searchOpen) setTimeout(() => searchRef.current?.focus(), 80);
    if (!searchOpen) setSearchQuery("");
  }, [searchOpen]);

  // Close on Escape
  useEffect(() => {
    const h = (e) => { if (e.key === "Escape") { setSearchOpen(false); setAboutOpen(false); }; };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, []);

  return (
    <div style={{ background: C.bg, color: C.ink, fontFamily: sans, WebkitFontSmoothing: "antialiased", MozOsxFontSmoothing: "grayscale", transition: "background .3s, color .3s" }}>

      {/* Film grain — fixed, non-interactive */}
      <GrainOverlay dark={dark} />

      {/* Fixed nav — always visible */}
      <nav style={{ position: "fixed", top: 0, left: 0, right: 0, zIndex: 200, height: 52, padding: `0 ${px}`, display: "flex", alignItems: "center", justifyContent: "space-between", background: C.navBg, backdropFilter: "blur(16px)", WebkitBackdropFilter: "blur(16px)", borderBottom: `1px solid ${C.border}`, transition: "background .3s, border-color .3s" }}>
        <NavPill onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })} C={C} dark={dark}>
          <span style={{ fontWeight: 500, fontSize: 15, letterSpacing: "-.015em" }}>yambo.</span>
        </NavPill>
        {!isMobile && (
          <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
            {["work","about","contact"].map(id => (
              <NavPill key={id} onClick={() => id === 'about' ? setAboutOpen(true) : go(id)} C={C} dark={dark}>{id}</NavPill>
            ))}
            {/* Search button */}
            <button onClick={() => setSearchOpen(true)} title="Search" style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 32, height: 32, borderRadius: 100, background: "transparent", border: `1px solid ${C.border}`, color: C.muted, cursor: "pointer", marginLeft: 4, transition: "border-color .2s, color .2s" }}
              onMouseEnter={e => { e.currentTarget.style.borderColor = C.muted; e.currentTarget.style.color = C.ink; }}
              onMouseLeave={e => { e.currentTarget.style.borderColor = C.border; e.currentTarget.style.color = C.muted; }}
            >
              <Search />
            </button>
            <ThemeBtn dark={dark} setDark={setDark} C={C} themeHv={thHov} themeHvP={thHovP} />
          </div>
        )}
        {isMobile && (
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setSearchOpen(true)} title="Search" style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 32, height: 32, borderRadius: 100, background: "transparent", border: `1px solid ${C.border}`, color: C.muted, cursor: "pointer" }}>
              <Search />
            </button>
            <ThemeBtn dark={dark} setDark={setDark} C={C} themeHv={thHov} themeHvP={thHovP} />
            <button onClick={() => setMenu(m => !m)} style={{ display: "flex", alignItems: "center", justifyContent: "center", width: 32, height: 32, borderRadius: 100, background: "transparent", border: `1px solid ${C.border}`, color: C.ink, cursor: "pointer" }}>
              {menuOpen ? <Close /> : <Menu />}
            </button>
          </div>
        )}
      </nav>

      
      {/* About modal */}
      {aboutOpen && (
        <div onClick={() => setAboutOpen(false)} style={{ position: "fixed", inset: 0, zIndex: 500, background: dark ? "rgba(0,0,0,0.75)" : "rgba(0,0,0,0.4)", backdropFilter: "blur(8px)", WebkitBackdropFilter: "blur(8px)", display: "flex", alignItems: "flex-end", justifyContent: "center", padding: "0", paddingTop: "60px" }}>
          <div onClick={e => e.stopPropagation()} style={{ width: "100%", maxWidth: 640, background: C.bg, border: `1px solid ${C.border}`, borderRadius: "16px 16px 0 0", overflow: "hidden", boxShadow: dark ? "0 32px 80px rgba(0,0,0,0.7)" : "0 32px 80px rgba(0,0,0,0.18)", maxHeight: "90vh", overflowY: "auto" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "20px 24px 0" }}>
              <span style={{ fontSize: 11, color: BRASS, letterSpacing: ".14em", textTransform: "uppercase", fontFamily: sans }}>About</span>
              <button onClick={() => setAboutOpen(false)} style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 6, cursor: "pointer", color: C.muted, fontFamily: sans, fontSize: 11, padding: "3px 8px" }}>ESC</button>
            </div>
            <div style={{ padding: "16px 24px 0" }}>
              <h2 style={{ fontFamily: sans, fontSize: "clamp(24px,4vw,34px)", fontWeight: 500, letterSpacing: "-.03em", color: C.ink, margin: 0 }}>Mike Yambo<span style={{ color: BRASS }}>.</span></h2>
            </div>
            <div style={{ height: 1, background: C.border, margin: "20px 24px" }} />
            <div style={{ padding: "0 24px 28px", display: "flex", flexDirection: "column", gap: 16 }}>
              <p style={{ fontFamily: sans, fontSize: 15, color: C.mid, lineHeight: 1.8, margin: 0 }}>Mike Yambo is an investigative data journalist and OSINT researcher. He previously worked at Nation Media Group as OSINT Lead at the Nation Forensic Unit, and currently works with AFP's digital investigations team.</p>
              <p style={{ fontFamily: sans, fontSize: 15, color: C.muted, lineHeight: 1.8, margin: 0 }}>His work focuses on forensic journalism spanning visual investigations, misinformation, conflict reporting, munitions research and accountability journalism — bridging traditional reporting and the tools of the digital age.</p>
              <p style={{ fontFamily: sans, fontSize: 15, color: C.muted, lineHeight: 1.8, margin: 0 }}>He is an award-winning journalist, lead investigator for Brothers in Arms — a cross-border Bellingcat collaboration on arms supply to Sudan — recognised with the Best Investigative Story award at the 2026 Annual Media Excellence Awards.</p>
              <p style={{ fontFamily: sans, fontSize: 15, color: C.muted, lineHeight: 1.8, margin: 0 }}>Mike believes rigorous, evidence-based journalism helps citizens understand power, conflict, and information ecosystems. He is passionate about open-source methods and making complex investigations accessible to wider audiences.</p>
              <div style={{ marginTop: 8, padding: "14px 18px", background: dark ? "rgba(201,168,76,0.08)" : "rgba(201,168,76,0.07)", border: `1px solid ${BRASS_BDR}`, borderRadius: 10 }}>
                <p style={{ fontFamily: sans, fontSize: 13, color: C.muted, lineHeight: 1.7, margin: 0 }}><span style={{ color: BRASS, fontWeight: 500 }}>Available for</span> — collaborations, fellowships, training programs, and speaking engagements on OSINT, digital investigations, misinformation, and investigative journalism.</p>
              </div>
              <a href="mailto:yambomike@proton.me" style={{ display: "inline-flex", alignItems: "center", gap: 6, marginTop: 4, fontFamily: sans, fontSize: 13, color: BRASS, textDecoration: "none", fontWeight: 500 }}>Get in touch →</a>
            </div>
          </div>
        </div>
      )}

      {/* Search overlay */}
      {searchOpen && (
        <div
          onClick={() => setSearchOpen(false)}
          style={{ position: "fixed", inset: 0, zIndex: 500, background: dark ? "rgba(0,0,0,0.7)" : "rgba(0,0,0,0.35)", backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)", display: "flex", alignItems: "flex-start", justifyContent: "center", padding: "clamp(64px,10vw,100px) 16px 16px" }}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{ width: "100%", maxWidth: 600, background: C.bg, border: `1px solid ${C.border}`, borderRadius: 14, overflow: "hidden", boxShadow: dark ? "0 24px 80px rgba(0,0,0,0.6)" : "0 24px 80px rgba(0,0,0,0.15)" }}
          >
            {/* Input row */}
            <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 18px", borderBottom: `1px solid ${C.border}` }}>
              <span style={{ color: C.muted, flexShrink: 0, display: "flex" }}><Search /></span>
              <input
                ref={searchRef}
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="Search investigations, topics, methods…"
                style={{ flex: 1, background: "none", border: "none", outline: "none", fontFamily: sans, fontSize: 16, color: C.ink, letterSpacing: "-.01em" }}
              />
              {searchQuery && (
                <button onClick={() => setSearchQuery("")} style={{ background: "none", border: "none", cursor: "pointer", color: C.muted, display: "flex", padding: 0, flexShrink: 0 }}>
                  <Close />
                </button>
              )}
              <button onClick={() => setSearchOpen(false)} style={{ background: "none", border: `1px solid ${C.border}`, borderRadius: 6, cursor: "pointer", color: C.muted, fontFamily: sans, fontSize: 11, padding: "3px 8px", flexShrink: 0, letterSpacing: ".04em" }}>ESC</button>
            </div>

            {/* Results */}
            {searchQuery.trim().length >= 2 && (
              <div style={{ maxHeight: 420, overflowY: "auto" }}>
                {results.length === 0 ? (
                  <div style={{ padding: "32px 18px", textAlign: "center" }}>
                    <p style={{ fontSize: 14, color: C.muted, fontFamily: sans }}>No results for "{searchQuery}"</p>
                  </div>
                ) : (
                  results.map((r, i) => (
                    <a key={r.href} href={r.href} target="_blank" rel="noopener noreferrer"
                      onClick={() => setSearchOpen(false)}
                      style={{ display: "block", padding: "14px 18px", textDecoration: "none", borderBottom: i < results.length - 1 ? `1px solid ${C.border}` : "none", transition: "background .15s" }}
                      onMouseEnter={e => e.currentTarget.style.background = C.border + "55"}
                      onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                        <span style={{ fontSize: 10, fontWeight: 500, letterSpacing: ".08em", color: C.faint, background: C.border, padding: "2px 7px", borderRadius: 100, fontFamily: sans, whiteSpace: "nowrap" }}>
                          {r.type.toUpperCase()}
                        </span>
                      </div>
                      <p style={{ fontSize: 14, fontWeight: 500, color: C.ink, margin: "0 0 3px", letterSpacing: "-.01em", lineHeight: 1.35, fontFamily: sans }}>{r.title}</p>
                      <p style={{ fontSize: 12, color: C.muted, margin: 0, fontFamily: sans }}>{r.meta}</p>
                    </a>
                  ))
                )}
              </div>
            )}

            {/* Empty / hint state */}
            {searchQuery.trim().length < 2 && (
              <div style={{ padding: "20px 18px" }}>
                <p style={{ fontSize: 12, color: C.faint, fontFamily: sans, marginBottom: 12, letterSpacing: ".04em" }}>QUICK JUMP</p>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  {["OSINT","Conflict","Satellite","Geolocation","Sudan","Kenya"].map(tag => (
                    <button key={tag} onClick={() => setSearchQuery(tag)} style={{ padding: "5px 12px", borderRadius: 100, fontSize: 12, fontFamily: sans, cursor: "pointer", background: "transparent", color: C.mid, border: `1px solid ${C.border}`, transition: "border-color .15s, color .15s" }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor = C.muted; e.currentTarget.style.color = C.ink; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor = C.border; e.currentTarget.style.color = C.mid; }}
                    >
                      {tag}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Mobile menu */}
      {menuOpen && (
        <div style={{ position: "fixed", top: 52, left: 0, right: 0, bottom: 0, zIndex: 190, background: C.bg, display: "flex", flexDirection: "column", transition: "background 0.3s", overflowY: "auto" }}>
          <div style={{ padding: "20px 24px 32px", display: "flex", flexDirection: "column", flex: 1 }}>
            {["work","about","contact"].map((id, i) => (
              <button key={id} onClick={() => go(id)} style={{
                display: "block", width: "100%", background: "none", border: "none",
                borderBottom: i < 2 ? `1px solid ${C.border}` : "none",
                padding: "16px 0", cursor: "pointer", fontFamily: sans,
                fontSize: 28, fontWeight: 500, letterSpacing: "-.03em",
                color: C.ink, textAlign: "left",
              }}>{id}</button>
            ))}
          </div>
        </div>
      )}

      {/* Hero — full viewport */}
      <section style={{
        minHeight: "100vh",
        display: "flex", flexDirection: "column", justifyContent: "center",
        padding: `52px ${px} clamp(40px,6vw,64px)`,
        position: "relative",
        overflow: "hidden",
      }}>
        {/* Parallax layer — moves slower than scroll */}
        <div style={{ ...inn, transform: `translateY(${parallaxY}px)`, transition: "transform 0s linear", willChange: "transform" }}>
          <p style={{
            fontFamily: sans, fontWeight: 300, letterSpacing: "-.025em", lineHeight: 1.2,
            fontSize: isMobile ? "clamp(20px,6vw,30px)" : "clamp(24px,4vw,44px)",
            color: C.ink, margin: 0, minHeight: "2.6em",
            opacity: loaded ? 1 : 0,
            transition: "opacity .4s ease .1s",
          }}>
            {typeDone ? (
              /* Once fully typed, render with bold highlights */
              <>
                Investigating power through{" "}
                <strong style={{ fontWeight: 800, letterSpacing: "-.03em" }}>data</strong>
                {" "}and{" "}
                <strong style={{ fontWeight: 800, letterSpacing: "-.03em" }}>open sources.</strong>
              </>
            ) : (
              /* While typing, render plain text */
              typed
            )}
            {/* Blinking cursor */}
            <span style={{
              display: "inline-block", width: "2px",
              height: "0.85em", background: BRASS,
              marginLeft: "3px", verticalAlign: "middle",
              animation: typeDone ? "cursorBlink 1.1s step-end infinite" : "none",
            }} />
          </p>

        </div>

          {/* Scroll indicator — centred, bright, outside parallax */}
          <div style={{
            position: "absolute",
            bottom: "clamp(24px, 4vh, 40px)",
            left: 0, right: 0,
            display: "flex", flexDirection: "column", alignItems: "center", gap: 8,
            opacity: loaded ? 1 : 0,
            transition: "opacity .6s ease 1s",
          }}>
            <span style={{ fontSize: 10, fontFamily: sans, letterSpacing: ".18em", color: BRASS, textTransform: "uppercase" }}>Scroll</span>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}>
              {[0, 1].map(i => (
                <svg key={i} width="14" height="8" viewBox="0 0 14 8" fill="none"
                  style={{ animation: `chevronBounce 1.6s ease ${i * 0.18}s infinite`, opacity: 1 - i * 0.35 }}
                >
                  <path d="M1 1l6 6 6-6" stroke={BRASS} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              ))}
            </div>
          </div>
        </section>

      <HR C={C} />

      {/* Bio — first section after hero */}
      <section style={{ ...sec }}>
        <ScrollSection>
          <div style={{ ...inn }}>
            <Fade>
              <h2 style={{ fontFamily: sans, fontSize: "clamp(22px,3vw,30px)", fontWeight: 500, letterSpacing: "-.025em", margin: "0 0 20px", lineHeight: 1.2, color: C.ink, transition: "color .3s" }}>
                Hi, I am Mike Yambo
              </h2>
            </Fade>
            <Fade delay={80}>
              <p style={{ fontSize: "clamp(15px,1.8vw,17px)", color: C.muted, lineHeight: 1.85, margin: "0 0 14px", maxWidth: 640, transition: "color .3s" }}>
                I'm an OSINT investigator and digital investigations reporter. My work spans conflict monitoring, weapons tracing, geolocation, satellite imagery analysis, and SOCMINT — covering East Africa and the wider continent.
              </p>
              <p style={{ fontSize: "clamp(15px,1.8vw,17px)", color: C.muted, lineHeight: 1.85, margin: 0, maxWidth: 640, transition: "color .3s" }}>
                I have collaborated with Bellingcat, reported for major African publications, and built open-source tools that automate the investigative process at scale.
              </p>
            </Fade>
          </div>
        </ScrollSection>
      </section>

      <HR C={C} />

      {/* Work */}
      <section id="work" style={{ ...sec }}>
        <ScrollSection>
          <div style={{ ...inn }}>
            <Fade>
              <p style={{ fontSize: 11, color: BRASS, letterSpacing: ".12em", margin: "0 0 36px", textTransform: "uppercase", transition: "color .3s" }}>Top investigations</p>
            </Fade>
            <div style={{ display: "flex", flexDirection: "column", gap: isMobile ? 48 : 68 }}>
              {WORK.map((w, i) => (
                <Fade key={w.slug} delay={i * 55}>
                  <WorkCard {...w} C={C} dark={dark} isMobile={isMobile} />
                </Fade>
              ))}
            </div>

            {/* More investigations */}
            <Fade style={{ marginTop: 52 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 0 }}>
                <p style={{ fontSize: 11, color: BRASS, letterSpacing: ".12em", margin: 0, flexShrink: 0, textTransform: "uppercase" }}>More investigations</p>
                <div style={{ flex: 1, height: 1, background: C.border }} />
              </div>
              {MORE_WORK.map(({ title, href, tag, year }, i) => (
                <MoreRow key={i} title={title} href={href} tag={tag} year={year} C={C} last={false} />
              ))}
              <ViewAllRow onClick={goInv} C={C} />
            </Fade>
          </div>
        </ScrollSection>
      </section>

      <HR C={C} />

      {/* About — experience only */}
      <section id="about" style={{ ...sec }}>
        <ScrollSection>
          <div style={{ ...inn }}>
            <Fade>
              <p style={{ fontSize: 11, color: BRASS, letterSpacing: ".12em", margin: "0 0 8px", textTransform: "uppercase", transition: "color .3s" }}>Experience</p>
              {EXPERIENCE.map(({ org, role, period }, i) => (
                <ExpRow key={org} org={org} role={role} period={period} C={C} last={i === EXPERIENCE.length - 1} />
              ))}
            </Fade>
          </div>
        </ScrollSection>
      </section>

      <HR C={C} />

      {/* Contact */}
      <section id="contact" style={{ ...sec }}>
        <ScrollSection>
          <div style={{ ...inn }}>
            <Fade>
              <h2 style={{ fontFamily: sans, fontSize: "clamp(22px,3vw,30px)", fontWeight: 500, letterSpacing: "-.025em", margin: "0 0 10px", lineHeight: 1.2, color: C.ink }}>Get in touch</h2>
              <p style={{ fontSize: 15, color: C.muted, lineHeight: 1.7, margin: "0 0 28px", maxWidth: 400 }}>Open to tip-offs, data collaboration, editorial partnerships, and speaking engagements.</p>
            </Fade>
            <Fade delay={70}>
              <div style={{ display: "flex", gap: 16, alignItems: "center", flexWrap: "wrap" }}>
                {[
                  { label: "Email",      href: "mailto:yambomike@proton.me",                         icon: <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 7 10 7 10-7"/></svg> },
                  { label: "X / Twitter",href: "https://x.com/YamboMike",                            icon: <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg> },
                  { label: "LinkedIn",   href: "https://www.linkedin.com/in/mike-yambo-b20b43163/",  icon: <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-2-2 2 2 0 0 0-2 2v7h-4v-7a6 6 0 0 1 6-6z"/><rect x="2" y="9" width="4" height="12"/><circle cx="4" cy="4" r="2"/></svg> },
                  { label: "GitHub",     href: "https://github.com/YamboMike-",                      icon: <svg width="21" height="21" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2C6.477 2 2 6.484 2 12.017c0 4.425 2.865 8.18 6.839 9.504.5.092.682-.217.682-.483 0-.237-.008-.868-.013-1.703-2.782.605-3.369-1.343-3.369-1.343-.454-1.158-1.11-1.466-1.11-1.466-.908-.62.069-.608.069-.608 1.003.07 1.531 1.032 1.531 1.032.892 1.53 2.341 1.088 2.91.832.092-.647.35-1.088.636-1.338-2.22-.253-4.555-1.113-4.555-4.951 0-1.093.39-1.988 1.029-2.688-.103-.253-.446-1.272.098-2.65 0 0 .84-.27 2.75 1.026A9.564 9.564 0 0 1 12 6.844a9.59 9.59 0 0 1 2.504.337c1.909-1.296 2.747-1.027 2.747-1.027.546 1.379.202 2.398.1 2.651.64.7 1.028 1.595 1.028 2.688 0 3.848-2.339 4.695-4.566 4.943.359.309.678.92.678 1.855 0 1.338-.012 2.419-.012 2.747 0 .268.18.58.688.482A10.02 10.02 0 0 0 22 12.017C22 6.484 17.522 2 12 2z"/></svg> },
                ].map(({ label, href, icon }) => (
                  <ContactIcon key={label} label={label} href={href} icon={icon} dark={dark} C={C} />
                ))}
              </div>
            </Fade>
          </div>
        </ScrollSection>
      </section>

      <HR C={C} />

      <footer style={{ padding: `18px ${px}` }}>
        <div style={{ ...inn, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
          <span style={{ fontSize: 14, color: C.faint, letterSpacing: "-.01em" }}>mike yambo. {new Date().getFullYear()}–∞</span>
          <span style={{ fontSize: 13, color: C.faint }}>OSINT Investigator</span>
        </div>
      </footer>

      <style>{`
        @keyframes mSlideIn    { from { opacity:0; transform:translateY(10px); } to { opacity:1; transform:none; } }
        @keyframes chevronBounce { 0%,100% { transform:translateY(0); opacity:1; } 50% { transform:translateY(5px); opacity:.5; } }
        @keyframes cursorBlink { 0%,100% { opacity:1; } 50% { opacity:0; } }
        @keyframes pinPulse    { 0% { r:8; opacity:.5; } 70% { r:22; opacity:0; } 100% { r:8; opacity:0; } }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        html { scroll-behavior: smooth; }
      `}</style>
    </div>
  );
}

// ─── App — simple router ──────────────────────────────────────────────────────

export default function App() {
  const [page, setPage] = useState("home");
  const [dark, setDark] = useState(
    typeof window !== "undefined" && window.matchMedia
      ? window.matchMedia("(prefers-color-scheme: dark)").matches
      : false
  );

  const goInv  = () => { setPage("investigations"); window.scrollTo(0, 0); };
  const goHome = () => { setPage("home");           window.scrollTo(0, 0); };

  useEffect(() => {
    if (!document.getElementById("yambo-fonts")) {
      const l = document.createElement("link");
      l.id = "yambo-fonts"; l.rel = "stylesheet";
      l.href = "https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500&display=swap";
      document.head.appendChild(l);
    }
  }, []);

  if (page === "investigations") return <InvestigationsPage dark={dark} setDark={setDark} goHome={goHome} />;
  return <HomePage dark={dark} setDark={setDark} goInv={goInv} />;
}
